mapper.select:
select tl.id, tl.area_id, tl.reservoir_id,tl.code, tl.name, tl.status, tl.location_type, tl.create_by, tl.create_time, tl.update_by, tl.update_time, tl.remark,
tl.location_row,tl.location_column,tl.location_plies,tl.same_batch_flag,tl.same_material_flag,tl.upper_limit,
tl.goods_allocation_status,tl.pallet_num,tl.extention_type,tl.pallet_node_id,tl.extention_frist_id,tl.erp_code,
ta.name as areaName,tr.name as reservoirName,tc.name as categoryName ,dtc.name as depositCategoryName,
tu.name as unitName,
tgs.name as goodShelfName
from t_location tl
left join t_area ta on ta.id = tl.area_id
left join t_reservoir tr on tr.id = tl.reservoir_id
left join t_good_shelf tgs on tl.good_shelf_id = tgs.id
left join t_category tc on tl.category_id = tc.id
left join t_category dtc on tl.deposit_category_id = dtc.id
left join t_unit tu on tl.unit_id = tu.id

    inner join sys_user u on u.user_name = tl.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tl.del_flag = '0'
    and tl.id = #{id}
    and tl.code = #{code}
    and tl.name like concat('%', #{name}, '%')
    and tl.status = #{status}
    and tl.area_id = #{areaId}
    and tl.reservoir_id = #{reservoirId}
    and tl.location_row = #{locationRow}
    and tl.location_column = #{locationColumn}
    and tl.location_plies = #{locationPlies}
    and tl.location_row >= #{startRow}
    and tl.location_column >= #{startColumn}
    and tl.location_plies >= #{startPlies}
    and tl.location_row <= #{endRow}
    and tl.location_column <= #{endColumn}
    and tl.location_plies <= #{endPlies}
    and tl.goods_allocation_status =
        #{goodsAllocationStatus}


        AND tl.pallet_num like concat('%', #{palletNum}, '%')

    and tl.same_material_flag =
        #{sameMaterialFlag}

    and tl.same_batch_flag = #{sameBatchFlag}
    and tl.category_id = #{categoryId}
    and tl.unit_id = #{unitId}
    and tl.location_type = #{locationType}
    and tl.pallet_node_id = #{palletNodeId}
    and tl.extention_frist_id = #{extentionFristId}
    and tl.extention_type = #{extentionType}


${params.dataScope}
order by tl.id desc

mapper.update:
update t_location tl
left join t_reservoir tr on tr.id = tl.reservoir_id
set tl.status = #{status}
 where tr.id = #{id}

update t_location

    area_id = #{areaId},
    reservoir_id = #{reservoirId},
    category_id = #{categoryId},deposit_category_id = #{categoryId},
    unit_id = #{unitId},
    same_material_flag = #{sameMaterialFlag},
    same_batch_flag = #{sameBatchFlag},
    upper_limit = #{upperLimit},
    good_shelf_id = #{goodShelfId},


    del_flag = '0'
    and location_row = #{locationRow}
    and location_column = #{locationColumn}
    and location_plies = #{locationPlies}
    and location_row >= #{startRow}
    and location_column >= #{startColumn}
    and location_plies >= #{startPlies}
    and location_row <= #{endRow}
    and location_column <= #{endColumn}
    and location_plies <= #{endPlies}

mapper.select:
select max(location_row) as maxRow,max(location_column) as maxColumn,max(location_plies) as maxPlies from
t_location tl

    tl.del_flag = '0'
    and tl.code = #{code}
    and tl.name like concat('%', #{name}, '%')
    and tl.status = #{status}
    and tl.area_id = #{areaId}
    and tl.reservoir_id = #{reservoirId}

SELECT tl.location_row as locationRow,COUNT(1) as totalcount,
    (SELECT COUNT(1)  FROM t_location tll   WHERE   tll.del_flag='0' and tll.`status`='1'
     AND tll.location_row=tl.location_row AND tll.location_type='0' AND tll.goods_allocation_status!=1 AND tll.reservoir_id=#{reservoirId}
     ) as inUser
FROM t_location tl WHERE tl.reservoir_id=#{reservoirId}  AND tl.del_flag='0' AND tl.location_type='0'
GROUP BY tl.location_row

select tl.id, tl.code, tl.name, tl.area_id, tl.reservoir_id, tl.category_id, tl.deposit_category_id, tl.unit_id, tl.same_material_flag, tl.same_batch_flag, tl.upper_limit, tl.location_row, tl.location_column, tl.location_plies, tl.goods_allocation_status, tl.status, tl.location_type, tl.pallet_num,
tl.extention_type,tl.extention_frist_id,tl.pallet_node_id
from t_location tl
left join t_tray b on tl.id = b.location_id
where tl.del_flag = '0' and b.id is null and (tl.pallet_num is null or tl.pallet_num = '')
